 13: @ConfigurationProperties(prefix = "sofascore.playwright")
 14: @Validated
 15: public class ProviderPlaywrightProperties {
 16: 
 17:     private static final int MAXIMUM_TCP_PORT = 65_535;
 18: 
 19:     private boolean enabled;
 20:     private Path workerJar;
 21: 
 22:     @Min(64)
 23:     @Max(512)
 24:     private int maximumHeapMib = 192;
 25: 
 26:     private Duration startupTimeout = Duration.ofSeconds(30);
 27:     private Duration requestTimeout = Duration.ofSeconds(10);
 28:     private Duration gracefulCloseTimeout = Duration.ofSeconds(5);
 29:     private boolean loopbackQualification;
 30:     private String loopbackOrigin = "";
 31: 
 32:     public boolean isEnabled() {
 33:         return enabled;
 34:     }
 35: 
 36:     public void setEnabled(boolean enabled) {
 37:         this.enabled = enabled;
 38:     }
 39: 
 40:     public Path getWorkerJar() {
 41:         return workerJar;
 42:     }
 43: 
 44:     public void setWorkerJar(Path workerJar) {
 45:         this.workerJar = workerJar == null || workerJar.toString().isBlank()
 46:                 ? null
 47:                 : workerJar;
 48:     }
 49: 
 50:     public int getMaximumHeapMib() {
 51:         return maximumHeapMib;
 52:     }
 53: 
 54:     public void setMaximumHeapMib(int maximumHeapMib) {
 55:         this.maximumHeapMib = maximumHeapMib;
 56:     }
 57: 
 58:     public Duration getStartupTimeout() {
 59:         return startupTimeout;
 60:     }
 61: 
 62:     public void setStartupTimeout(Duration startupTimeout) {
 63:         this.startupTimeout = startupTimeout;
 64:     }
 65: 
 66:     public Duration getRequestTimeout() {
 67:         return requestTimeout;
 68:     }
 69: 
 70:     public void setRequestTimeout(Duration requestTimeout) {
 71:         this.requestTimeout = requestTimeout;
 72:     }
 73: 
 74:     public Duration getGracefulCloseTimeout() {
 75:         return gracefulCloseTimeout;
 76:     }
 77: 
 78:     public void setGracefulCloseTimeout(Duration gracefulCloseTimeout) {
 79:         this.gracefulCloseTimeout = gracefulCloseTimeout;
 80:     }
 81: 
 82:     public boolean isLoopbackQualification() {
 83:         return loopbackQualification;
 84:     }
 85: 
 86:     public void setLoopbackQualification(boolean loopbackQualification) {
 87:         this.loopbackQualification = loopbackQualification;
 88:     }
 89: 
 90:     public String getLoopbackOrigin() {
 91:         return loopbackOrigin;
 92:     }
 93: 
 94:     public void setLoopbackOrigin(String loopbackOrigin) {
 95:         this.loopbackOrigin = loopbackOrigin == null ? "" : loopbackOrigin.trim();
 96:     }
 97: 
 98:     @AssertTrue(message = "Playwright timeouts and loopback qualification must remain bounded")
 99:     public boolean isSafeConfiguration() {
100:         if (!bounded(startupTimeout, Duration.ofSeconds(60))
101:                 || !bounded(requestTimeout, Duration.ofSeconds(60))
102:                 || !bounded(gracefulCloseTimeout, Duration.ofSeconds(5))) {
103:             return false;
104:         }
105:         if (!loopbackQualification) {
106:             return loopbackOrigin.isEmpty();
107:         }
108:         try {
109:             URI origin = URI.create(loopbackOrigin);
110:             return "http".equals(origin.getScheme())
111:                     && "127.0.0.1".equals(origin.getHost())
112:                     && origin.getPort() >= 1
113:                     && origin.getPort() <= MAXIMUM_TCP_PORT
114:                     && origin.getRawUserInfo() == null
115:                     && origin.getRawQuery() == null
116:                     && origin.getRawFragment() == null
117:                     && (origin.getRawPath() == null || origin.getRawPath().isEmpty());
118:         }
119:         catch (IllegalArgumentException exception) {
120:             return false;
121:         }
122:     }
123: 
124:     private static boolean bounded(Duration value, Duration maximum) {
125:         return value != null
126:                 && !value.isZero()
127:                 && !value.isNegative()
128:                 && value.compareTo(maximum) <= 0;
129:     }
130: }

  1: package com.bettingproject.sofascorelocal.provider.playwright.worker;
  2: 
  3: import java.net.URI;
  4: import java.net.URISyntaxException;
  5: import java.time.LocalDate;
  6: import java.util.Map;
  7: import java.util.Objects;
  8: 
  9: final class ProviderPlaywrightWorkerConfiguration {
 10: 
 11:     private static final int MAXIMUM_TCP_PORT = 65_535;
 12: 
 13:     static final String IPC_PORT = "SOFASCORE_PLAYWRIGHT_IPC_PORT";
 14:     static final String IPC_TOKEN = "SOFASCORE_PLAYWRIGHT_IPC_TOKEN";
 15:     static final String LOOPBACK_ORIGIN = "SOFASCORE_PLAYWRIGHT_LOOPBACK_ORIGIN";
 16:     static final String LOOPBACK_QUALIFICATION = "SOFASCORE_PLAYWRIGHT_LOOPBACK_QUALIFICATION";
 17:     static final URI PROVIDER_ORIGIN = URI.create("https://www.sofascore.com");
 18: 
 19:     private final int ipcPort;
 20:     private final String token;
 21:     private final URI origin;
 22: 
 23:     private ProviderPlaywrightWorkerConfiguration(int ipcPort, String token, URI origin) {
 24:         this.ipcPort = ipcPort;
 25:         this.token = token;
 26:         this.origin = origin;
 27:     }
 28: 
 29:     static ProviderPlaywrightWorkerConfiguration fromEnvironment(Map<String, String> environment) {
 30:         Objects.requireNonNull(environment, "environment");
 31:         int ipcPort = parsePort(environment.get(IPC_PORT));
 32:         String token = environment.get(IPC_TOKEN);
 33:         ProviderPlaywrightWorkerProtocol.validateToken(token);
 34:         URI origin = parseOrigin(environment);
 35:         return new ProviderPlaywrightWorkerConfiguration(ipcPort, token, origin);
 36:     }
 37: 
 38:     int ipcPort() {
 39:         return ipcPort;
 40:     }
 41: 
 42:     String token() {
 43:         return token;
 44:     }
 45: 
 46:     URI uriFor(ProviderPlaywrightWorkerProtocol.GetCommand command) {
 47:         String path = switch (command.endpoint()) {
 48:             case SCHEDULED_EVENTS -> "/api/v1/sport/football/scheduled-tournaments/"
 49:                     + isoDate(command.date()) + "/page/" + command.page();
 50:             case TOURNAMENT_SCHEDULED_EVENTS -> "/api/v1/unique-tournament/"
 51:                     + command.tournamentId() + "/scheduled-events/" + isoDate(command.date());
 52:             case EVENT_DETAILS -> "/api/v1/event/" + command.eventId();
 53:             case EVENT_STATISTICS ->
 54:                     "/api/v1/event/" + command.eventId() + "/statistics";
 55:             case EVENT_INCIDENTS ->
 56:                     "/api/v1/event/" + command.eventId() + "/incidents";
 57:             case EVENT_LINEUPS ->
 58:                     "/api/v1/event/" + command.eventId() + "/lineups";
 59:         };
 60:         return origin.resolve(path);
 61:     }
 62: 
 63:     private static int parsePort(String value) {
 64:         try {
 65:             int port = Integer.parseInt(value);
 66:             if (port < 1 || port > MAXIMUM_TCP_PORT) {
 67:                 throw new IllegalArgumentException();
 68:             }
 69:             return port;
 70:         }
 71:         catch (RuntimeException exception) {
 72:             throw new IllegalArgumentException(
 73:                     ProviderPlaywrightWorkerProtocol.FailureCode.INVALID_CONFIGURATION.name(), exception);
 74:         }
 75:     }
 76: 
 77:     private static URI parseOrigin(Map<String, String> environment) {
 78:         String qualification = environment.get(LOOPBACK_QUALIFICATION);
 79:         String configuredOrigin = environment.get(LOOPBACK_ORIGIN);
 80:         if (!"true".equals(qualification)) {
 81:             if (configuredOrigin != null && !configuredOrigin.isBlank()) {
 82:                 throw invalidConfiguration();
 83:             }
 84:             return PROVIDER_ORIGIN;
 85:         }
 86:         if (configuredOrigin == null || configuredOrigin.isBlank()) {
 87:             throw invalidConfiguration();
 88:         }
 89:         try {
 90:             URI candidate = new URI(configuredOrigin);
 91:             if (!"http".equals(candidate.getScheme())
 92:                     || !"127.0.0.1".equals(candidate.getHost())
 93:                     || candidate.getPort() < 1
 94:                     || candidate.getPort() > MAXIMUM_TCP_PORT
 95:                     || candidate.getRawUserInfo() != null
 96:                     || candidate.getRawQuery() != null
 97:                     || candidate.getRawFragment() != null
 98:                     || candidate.getRawPath() == null
 99:                     || !candidate.getRawPath().isEmpty()) {
100:                 throw invalidConfiguration();
101:             }
102:             return candidate;
103:         }
104:         catch (URISyntaxException exception) {
105:             throw new IllegalArgumentException(
106:                     ProviderPlaywrightWorkerProtocol.FailureCode.INVALID_CONFIGURATION.name(), exception);
107:         }
108:     }
109: 
110:     private static String isoDate(LocalDate date) {
111:         return date.toString();
112:     }
113: 
114:     private static IllegalArgumentException invalidConfiguration() {
115:         return new IllegalArgumentException(
116:                 ProviderPlaywrightWorkerProtocol.FailureCode.INVALID_CONFIGURATION.name());
117:     }
118: }

