 3: import java.net.URI;
 4: import java.net.URISyntaxException;
 5: import java.time.LocalDate;
 6: import java.util.Objects;
 7: 
 8: public record ScheduledEventsTransportRequest(
 9:         URI loopbackOrigin,
10:         LocalDate date) {
11: 
12:     static final String SIMULATED_PATH = "/simulated/scheduled-events";
13: 
14:     public ScheduledEventsTransportRequest {
15:         Objects.requireNonNull(loopbackOrigin, "loopbackOrigin");
16:         Objects.requireNonNull(date, "date");
17:         requireExactLoopbackOrigin(loopbackOrigin);
18:     }
19: 
20:     public SofascoreEndpointType endpointType() {
21:         return SofascoreEndpointType.SCHEDULED_EVENTS;
22:     }
23: 
24:     public String requestKey() {
25:         return endpointType().name() + "|date=" + date;
26:     }
27: 
28:     public URI targetUri() {
29:         try {
30:             return new URI(
31:                     "http",
32:                     null,
33:                     "127.0.0.1",
34:                     loopbackOrigin.getPort(),
35:                     SIMULATED_PATH,
36:                     "date=" + date,
37:                     null);
38:         }
39:         catch (URISyntaxException exception) {
40:             throw new IllegalStateException("validated loopback request is not a valid URI", exception);
41:         }
42:     }
43: 
44:     private static void requireExactLoopbackOrigin(URI origin) {
45:         boolean rootPath = origin.getRawPath() == null
46:                 || origin.getRawPath().isEmpty()
47:                 || origin.getRawPath().equals("/");
48:         if (!origin.isAbsolute()
49:                 || !"http".equals(origin.getScheme())
50:                 || !"127.0.0.1".equals(origin.getHost())
51:                 || origin.getPort() < 1
52:                 || origin.getPort() > 65_535
53:                 || origin.getRawUserInfo() != null
54:                 || !rootPath
55:                 || origin.getRawQuery() != null
56:                 || origin.getRawFragment() != null) {
57:             throw new IllegalArgumentException(
58:                     "loopbackOrigin must be exactly http://127.0.0.1:<port>");
59:         }
60:     }
61: }

